import { Injectable } from '@angular/core';export enum LocalStorageKeys {  CACHED_PATHS = 'cachedPaths',  LANGUAGE_PREFERENCE = 'languagePreference',  SHARE_EXPERIENCE_MODAL_READ = 'shareExperienceModalRead',  INBOX_IVRR_AUDIO_RECORDER_ESCAPE_KEY_INFO = 'inboxIvrrAudioRecorderEscapeKeyInfo2',  OUTBOX_IVRR_AUDIO_RECORDER_INFO = 'outboxIvrrAudioRecorderInfo',  LOCATION_COMPONENT_READ = 'locationComponentRead',}@Injectable({ providedIn: 'root' })export class LocalStorageService {  set(key: LocalStorageKeys, payload: any | string): void {    const stringified = typeof payload === 'string' ? payload : JSON.stringify(payload);    if (stringified === undefined || stringified === 'undefined') {      return;    }    localStorage.setItem(key, stringified);  }  get<T>(key: LocalStorageKeys): T | null {    const rawValue = localStorage.getItem(key);    if (!rawValue) {      return null;    }    try {      return JSON.parse(rawValue);    } catch (e) {      return rawValue as any as T;    }  }  delete(key: LocalStorageKeys): void {    localStorage.removeItem(key);  }}