import { Pipe, PipeTransform } from '@angular/core';import { LocalStorageKeys, LocalStorageService } from '@core/services/local-storage/local-storage.service';import { TranslateService } from '@ngx-translate/core';import { CountriesService } from '@shared/services/countries.service';import { Observable, of, shareReplay } from 'rxjs';import { map, tap } from 'rxjs/operators';export interface CachedPath {  regionId: number;  path: string;}@Pipe({  name: 'placeOrCountry',  pure: true,})export class PlacePipe implements PipeTransform {  constructor(private translate: TranslateService, private countriesService: CountriesService, private localStorage: LocalStorageService) {}  transform(regionId: number, countryCode: string): Observable<string> {    const countryName = this.translate.instant(`country_name.${countryCode}`);    if (regionId) {      const cashedPaths: CachedPath[] = this.localStorage.get<CachedPath[]>(LocalStorageKeys.CACHED_PATHS) || new Array<CachedPath>();      const cachedPath = cashedPaths.find((cachedPath) => cachedPath.regionId === regionId);      if (cachedPath) {        return of(cachedPath.path);      }      return this.countriesService.getRegionPath(regionId).pipe(        shareReplay(),        map((path) => {          return path.path ? path.path + ', ' + countryName : null;        }),        tap((path) => {          cashedPaths.push(<CachedPath>{            regionId,            path,          });          this.localStorage.set(LocalStorageKeys.CACHED_PATHS, cashedPaths);        }),      );    } else {      return of((countryCode && countryName) || this.translate.instant(`filtersV2.loaction.label`) + ' 1');    }  }}